"""Chinese offline report for the six predeclared coverage comparisons."""

import csv
import gzip
import html
import json
from datetime import datetime
from pathlib import Path

from .config import ResearchError
from .coverage_expansion import DEFAULT_PLAN, declaration
from .storage import SpaceBudget, directory_bytes


def csv_rows(path):
    with gzip.open(path,"rt",encoding="utf-8-sig") as stream:
        return list(csv.DictReader(stream))


def build(plan_path=DEFAULT_PLAN):
    path,plan,parent = declaration(plan_path)
    root = Path(plan["budget"]["roots"][1])
    scenarios=[]
    for month in plan["months"]+["2026-09"]:
        for k in plan["candidate_k"]:
            latest=root/(month+"_k"+str(k)+"_latest.json")
            if not latest.exists(): raise ResearchError("报告等待完整对照："+latest.name)
            record=json.loads(latest.read_text()); run=Path(record['directory'])
            review=json.loads((run/'independent_coverage_audit.json').read_text())
            if review['status']!='passed': raise ResearchError("报告要求逐笔独立复核通过")
            summary=json.loads((run/'summary.json').read_text()); manifest=json.loads((run/'manifest.json').read_text())
            trades=csv_rows(run/'trades.csv.gz')
            paths={(p['contract'],p['entry_time']):p for p in review['paths']}
            if len(paths)!=len(trades):raise ResearchError('成交与独立保护路径数量不符')
            for t in trades:
                for field in ['quantity','rank','entry_price','exit_price','net_pnl','fees','holding_minutes','stop_price','target_price']:
                    t[field]=float(t[field])
                t['slope']=json.loads(t['entry_snapshot'])['slope_band']
                t['protection']=json.loads(t['entry_protection'])
            scenarios.append({**record,'trades':trades,'funnel':summary['signal_funnel']['sequential'],
                'rejections':summary['signal_funnel']['independent_rejections'],
                'independent_review':'passed','paths':[paths[(t['contract'],t['entry_time'])] for t in trades],
                'rejections_scope':'selected_candidates' if manifest.get('configuration',{}).get('storage',{}).get('record_unselected_signals') is False else 'all_ranked_candidates',
                'covered_products':len({x['product'] for x in manifest['data_coverage']})})
    coverage=[]
    for month in plan['months']:
        input_root=path.parent/month
        acquired=json.loads((input_root/'acquisition_summary.json').read_text())
        meta=json.loads((input_root/'metadata.json').read_text())['contracts']
        products={r['symbol']+'.'+r['exchange']:r['product'] for r in meta}
        rows=acquired['coverage']; execution=json.loads((root/month/'execution_coverage.json').read_text())
        coverage.append({'month':month,'products':len({products[r['contract']] for r in rows if r['rows']}),
            'contracts':len(rows),'minutes':acquired['minute_rows'],'days':len({d for r in rows for d in r['dates'] if d.startswith(month)}),
            'execution_products':len(execution['execution_products']),'missing_rules':execution['rule_rejections'],
            'download_errors':len(acquired['errors']),'source_errors':len(execution['source_errors'])})
    policy=json.loads((path.parent/'cloud_policy.json').read_text())
    cloud=json.loads((Path(policy['local_state'])/'status.json').read_text())
    reading=json.loads((root/'cloud_read_verification.json').read_text())
    if cloud['status']!='verified' or reading['status']!='passed':raise ResearchError('云端同步及实际按需读回尚未验收')
    changes=[]
    for month in plan['months']+['2026-09']:
        control=next(s for s in scenarios if s['month']==month and s['k']==2)
        expanded=next(s for s in scenarios if s['month']==month and s['k']==5)
        key=lambda t:(t['contract'],t['direction'],t['entry_time'])
        a={key(t):t for t in control['trades']}; b={key(t):t for t in expanded['trades']}
        shared=a.keys()&b.keys()
        changes.append({'month':month,'added':[t for ident,t in b.items() if ident not in a],
            'removed':[t for ident,t in a.items() if ident not in b],
            'shared_count':len(shared),'shared_net_delta':sum(b[ident]['net_pnl']-a[ident]['net_pnl'] for ident in shared),
            'net_delta':expanded['metrics']['net_profit']-control['metrics']['net_profit']})
    report={'scenarios':scenarios,'coverage':coverage,'changes':changes,'strategy':parent['strategy'],'risk':parent['risk'],
            'cloud':cloud,'cloud_read':reading,'policy':policy,'local_bytes':directory_bytes(plan['budget']['roots']),
            'created':datetime.now().astimezone().isoformat(),'sample_note':'7、8月：9月参数确定后的历史回放；9月14—23日：已多次查看的开发样本。9月24—30日保持锁定。'}
    totals={k:{'profit':sum(s['metrics']['net_profit'] for s in scenarios if s['k']==k),
               'trades':sum(s['metrics']['trade_count'] for s in scenarios if s['k']==k)} for k in plan['candidate_k']}
    report['totals']=totals
    report['research_days']=sum(next(s['metrics']['daily_count'] for s in scenarios if s['month']==month) for month in plan['months']+['2026-09'])
    more=totals[5]['trades']-totals[2]['trades']; delta=totals[5]['profit']-totals[2]['profit']
    headline=f"扩到 K=5 后，交易增加 {more} 笔，跨窗口净收益变化 {delta:+,.2f} 元。"
    payload=json.dumps(report,ensure_ascii=False,allow_nan=False).replace('<','\\u003c')
    document=TEMPLATE.replace('__DATA__',payload).replace('__HEADLINE__',html.escape(headline)).replace('__BUILT__',html.escape(report['created'][:16].replace('T',' ')))
    target=root/'strategy_coverage_review.html'; budget=SpaceBudget(plan['budget']);budget.check(target,reserve=len(document.encode()))
    temporary=target.with_suffix('.html.partial');temporary.write_text(document);temporary.replace(target)
    (root/'report_data.json').write_text(json.dumps(report,ensure_ascii=False,indent=2))
    print(json.dumps({'report':str(target),'totals':totals,'added_trades':more,'profit_delta':delta},ensure_ascii=False))
    return target


